// TieredAmount returns the charge for quantity units on a metered plan's tiers, in minor units. Graduated: each unit is
// priced at the tier it falls in, and every tier that a unit falls in adds its flat amount. Volume: every unit is priced at
// the tier the total falls in, which adds its flat amount. A tier's UpTo is inclusive, and a quantity of 0 costs 0.
func TieredAmount(tiers []store.Tier, mode store.TiersMode, quantity int64) int64 {
	if quantity <= 0 {
		return 0
	}
	var total int64
	if mode == store.Volume {
		for _, t := range tiers {
			if t.UpTo == nil || quantity <= *t.UpTo {
				return quantity*t.UnitAmount + t.FlatAmount
			}
		}
		return 0
	}
	var from int64 // units before this tier
	for _, t := range tiers {
		if quantity <= from {
			break
		}
		units := quantity - from
		if t.UpTo != nil && *t.UpTo-from < units {
			units = *t.UpTo - from
		}
		total += units*t.UnitAmount + t.FlatAmount
		if t.UpTo == nil {
			break
		}
		from = *t.UpTo
	}
	return total
}

