// tierIn is a tier as people type it: amounts in major units ("0.10"). FlatAmount may be left out.
type tierIn struct {
	UpTo       *json.Number `json:"up_to"`
	UnitAmount string       `json:"unit_amount"`
	FlatAmount string       `json:"flat_amount"`
}

// readTiers converts tiers in major units to tiers in minor units. A tier that cannot be read is an invalid tier.
func readTiers(in []tierIn, c money.Currency) ([]store.Tier, error) {
	if len(in) == 0 {
		return nil, fmt.Errorf("%w: a plan needs at least one tier", store.ErrInvalidTiers)
	}
	out := make([]store.Tier, 0, len(in))
	for _, t := range in {
		var tier store.Tier
		if t.UpTo != nil {
			n, err := strconv.ParseInt(t.UpTo.String(), 10, 64)
			if err != nil {
				return nil, fmt.Errorf("%w: up_to %s is not a whole number", store.ErrInvalidTiers, t.UpTo)
			}
			tier.UpTo = &n
		}
		unit, err := money.ParseMajor(t.UnitAmount, c)
		if err != nil {
			return nil, fmt.Errorf("%w: unit_amount: %v", store.ErrInvalidTiers, err)
		}
		tier.UnitAmount = unit
		if t.FlatAmount != "" {
			flat, err := money.ParseMajor(t.FlatAmount, c)
			if err != nil {
				return nil, fmt.Errorf("%w: flat_amount: %v", store.ErrInvalidTiers, err)
			}
			tier.FlatAmount = flat
		}
		out = append(out, tier)
	}
	return out, nil
}

