cat >> internal/billing/billing_test.go <<'EOF'

func TestTieredAmount(t *testing.T) {
	upTo := func(n int64) *int64 { return &n }
	tiers := []store.Tier{{UpTo: upTo(10), UnitAmount: 100}, {UpTo: upTo(20), UnitAmount: 50, FlatAmount: 300}, {UnitAmount: 25}}
	for _, c := range []struct {
		mode store.TiersMode
		q    int64
		want int64
	}{
		{store.Graduated, 0, 0},
		{store.Graduated, 5, 500},
		{store.Graduated, 10, 1000},
		{store.Graduated, 15, 1550}, // 10*100 + 5*50 + 300
		{store.Graduated, 20, 1800}, // 10*100 + 10*50 + 300
		{store.Graduated, 25, 1925}, // 1800 + 5*25
		{store.Volume, 0, 0},
		{store.Volume, 5, 500},
		{store.Volume, 10, 1000}, // up_to is inclusive: still the first tier
		{store.Volume, 11, 850},  // 11*50 + 300
		{store.Volume, 20, 1300}, // 20*50 + 300
		{store.Volume, 25, 625},  // 25*25
	} {
		if got := TieredAmount(tiers, c.mode, c.q); got != c.want {
			t.Errorf("TieredAmount(%s, %d) = %d, want %d", c.mode, c.q, got, c.want)
		}
	}
}
EOF
