func TestPlanTiersValidation(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	upTo := func(n int64) *int64 { return &n }
	good := []Tier{{UpTo: upTo(10), UnitAmount: 100}, {UpTo: upTo(20), UnitAmount: 50, FlatAmount: 300}, {UnitAmount: 25}}
	plan := func(usage UsageType, mode TiersMode, tiers []Tier) Plan {
		return Plan{OrgID: a.ID, Name: "API", Currency: money.USD, Interval: Monthly, UsageType: usage, TiersMode: mode, Tiers: tiers}
	}
	for _, c := range []struct {
		name string
		p    Plan
	}{
		{"tiers on a licensed plan", plan(Licensed, Graduated, good)},
		{"tiers without a mode", plan(Metered, "", good)},
		{"unknown mode", plan(Metered, "stepped", good)},
		{"mode without tiers", plan(Metered, Volume, nil)},
		{"no upper limit before the last tier", plan(Metered, Graduated, []Tier{{UnitAmount: 1}, {UnitAmount: 2}})},
		{"last tier with an upper limit", plan(Metered, Graduated, []Tier{{UpTo: upTo(10), UnitAmount: 1}})},
		{"not ascending", plan(Metered, Graduated, []Tier{{UpTo: upTo(10)}, {UpTo: upTo(10)}, {}})},
		{"zero up_to", plan(Metered, Graduated, []Tier{{UpTo: upTo(0)}, {}})},
		{"negative amount", plan(Metered, Graduated, []Tier{{UpTo: upTo(10), UnitAmount: -1}, {}})},
		{"negative flat amount", plan(Metered, Volume, []Tier{{UpTo: upTo(10), FlatAmount: -1}, {}})},
	} {
		if _, err := s.CreatePlan(c.p, t0); !errors.Is(err, ErrInvalidTiers) {
			t.Errorf("%s: CreatePlan = %v, want ErrInvalidTiers", c.name, err)
		}
	}
	p, err := s.CreatePlan(plan(Metered, Graduated, good), t0)
	if err != nil || p.TiersMode != Graduated || !reflect.DeepEqual(p.Tiers, good) {
		t.Fatalf("CreatePlan = %+v, %v", p, err)
	}
	if up, err := s.UpdatePlan(a.ID, p.ID, func(p *Plan) error { p.TiersMode, p.Tiers = Volume, nil; return nil }); err != nil || up.TiersMode != Graduated || len(up.Tiers) != 3 {
		t.Fatalf("UpdatePlan = %+v, %v (the tiers must not change)", up, err)
	}
}

