// tierIn is a tier as people type it: amounts in major units ("0.10"). FlatAmount may be left out.
type tierIn struct {
	UpTo       *json.Number `json:"up_to"`
	UnitAmount string       `json:"unit_amount"`
	FlatAmount string       `json:"flat_amount"`
}

// readTiers converts tiers in major units to tiers in minor units. A tier that cannot be read is an invalid tier.
func readTiers(in []tierIn, c money.Currency) ([]store.Tier, error) {
	if len(in) == 0 {
		return nil, fmt.Errorf("%w: a plan needs at least one tier", store.ErrInvalidTiers)
	}
	out := make([]store.Tier, 0, len(in))
	for _, t := range in {
		var tier store.Tier
		if t.UpTo != nil {
			n, err := strconv.ParseInt(t.UpTo.String(), 10, 64)
			if err != nil {
				return nil, fmt.Errorf("%w: up_to %s is not a whole number", store.ErrInvalidTiers, t.UpTo)
			}
			tier.UpTo = &n
		}
		unit, err := money.ParseMajor(t.UnitAmount, c)
		if err != nil {
			return nil, fmt.Errorf("%w: unit_amount: %v", store.ErrInvalidTiers, err)
		}
		tier.UnitAmount = unit
		if t.FlatAmount != "" {
			flat, err := money.ParseMajor(t.FlatAmount, c)
			if err != nil {
				return nil, fmt.Errorf("%w: flat_amount: %v", store.ErrInvalidTiers, err)
			}
			tier.FlatAmount = flat
		}
		out = append(out, tier)
	}
	return out, nil
}

// createPlan takes the price in major units, as a string ("12.50"), the way people type it. A metered plan can have tiers
// instead of a price; its tiers are in major units too.
func (s *Server) createPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	var in struct {
		Name      string          `json:"name"`
		Currency  money.Currency  `json:"currency"`
		Price     string          `json:"price"`
		Interval  store.Interval  `json:"interval"`
		UsageType store.UsageType `json:"usage_type"`
		TrialDays int             `json:"trial_days"`
		TiersMode store.TiersMode `json:"tiers_mode"`
		Tiers     []tierIn        `json:"tiers"`
	}
	if !decode(w, r, &in) {
		return
	}
	pl := store.Plan{OrgID: p.OrgID, Name: in.Name, Currency: in.Currency, Interval: in.Interval, UsageType: in.UsageType,
		TrialDays: in.TrialDays, TiersMode: in.TiersMode}
	if in.TiersMode != "" || in.Tiers != nil {
		tiers, err := readTiers(in.Tiers, in.Currency)
		if err != nil {
			s.storeError(w, err)
			return
		}
		pl.Tiers = tiers
	} else {
		amount, err := money.ParseMajor(in.Price, in.Currency)
		if err != nil {
			if errors.Is(err, money.ErrInvalidAmount) {
				writeError(w, http.StatusUnprocessableEntity, "invalid_amount", err.Error())
				return
			}
			s.storeError(w, err)
			return
		}
		pl.UnitAmount = amount
	}
	pl, err := s.store.CreatePlan(pl, s.clock.Now())
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusCreated, viewPlan(pl))
}

func (s *Server) getPlan(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	pl, ok := s.store.Plan(p.OrgID, r.PathValue("id"))
	if !ok {
		writeError(w, http.StatusNotFound, "not_found", "no such plan")
		return
	}
	writeJSON(w, http.StatusOK, viewPlan(pl))
}
