207	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
208	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
209	// payment method stays open and counts as paid here (it is paid by hand).
210	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
211		var lines []store.Line
212		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
213		switch plan.UsageType {
214		case store.Licensed:
215			if plan.UnitAmount > 0 {
216				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
217			}
218		case store.Metered:
219			used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end)
220			switch {
221			case plan.TiersMode != "":
222				if used == 0 {
223					return true, nil
224				}
225				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: 1,
226					UnitAmount: billing.TieredAmount(plan.Tiers, plan.TiersMode, used)})
227			case used > 0:
228				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
229			}
230		}
231		ps, pe := start, end
232		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
233			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
234		if err != nil {
235			return false, err
236		}
237		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
238		_, _, err = s.Payments.Pay(ctx, sub.OrgID, inv.ID, "")
239		var decline *payments.DeclineError
240		switch {
241		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
242			return true, nil
243		case errors.As(err, &decline):
244			return false, nil
245		default:
246			return false, err
247		}
248	}
